import heapq

class Node:
    def __init__(self, x, y, cost):
        self.x = x
        self.y = y
        self.cost = cost
        self.g = cost  # Cost from start node to current node
        self.h = 0  # Heuristic cost to the goal
        self.f = 0  # Total cost (g + h)
        self.parent = None  # Parent node

    def __lt__(self, other):
        return self.f < other.f

def heuristic(a, b):
    """Manhattan distance heuristic"""
    return abs(a.x - b.x) + abs(a.y - b.y)

def a_star_search(grid, start, end):
    if start == end:
        return None, None

    open_set = []
    closed_set = set()
    start_node = Node(start[0], start[1], 0)
    heapq.heappush(open_set, start_node)

    while open_set:
        current_node = heapq.heappop(open_set)
        closed_set.add((current_node.x, current_node.y))

        if current_node.x == end[0] and current_node.y == end[1]:
            path = []
            while current_node:
                path.append((current_node.x, current_node.y))
                current_node = current_node.parent
            path.reverse()
            return path, current_node.g

        neighbors = []
        if current_node.x > 0 and grid[current_node.x-1][current_node.y] != 'X':
            neighbors.append(Node(current_node.x-1, current_node.y, current_node.g + 1))
        if current_node.x < len(grid) - 1 and grid[current_node.x+1][current_node.y] != 'X':
            neighbors.append(Node(current_node.x+1, current_node.y, current_node.g + 1))
        if current_node.y > 0 and grid[current_node.x][current_node.y-1] != 'X':
            neighbors.append(Node(current_node.x, current_node.y-1, current_node.g + 1))
        if current_node.y < len(grid[0]) - 1 and grid[current_node.x][current_node.y+1] != 'X':
            neighbors.append(Node(current_node.x, current_node.y+1, current_node.g + 1))

        for neighbor in neighbors:
            if (neighbor.x, neighbor.y) in closed_set:
                continue

            tentative_g = current_node.g + 1
            if neighbor not in open_set:
                heapq.heappush(open_set, neighbor)
            else:
                if tentative_g < neighbor.g:
                    neighbor.g = tentative_g
                    neighbor.parent = current_node
                    if open_set and open_set[open_set.index(neighbor)] < neighbor:
                        heapq.heapreplace(open_set, neighbor)

    return None, None

